const seriesPath = (id) => `/series/${id}/`;
function collectSeries(posts) {
  const groups = new Map();
  for (const post of posts) {
    const { series, seriesTitle, seriesOrder } = post.frontmatter;
    if (series == null && seriesTitle == null && seriesOrder == null) continue;
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(series || '') ||
        !seriesTitle?.trim() || !Number.isInteger(seriesOrder) || seriesOrder < 1)
      throw new Error(`Invalid series metadata: ${post.frontmatter.slug}`);
    if (!groups.has(series)) groups.set(series, { id: series, title: seriesTitle, posts: [] });
    const group = groups.get(series);
    if (group.title !== seriesTitle || group.posts.some(p => p.frontmatter.seriesOrder === seriesOrder))
      throw new Error(`Conflicting series title or duplicate part number: ${series}`);
    group.posts.push(post);
  }
  for (const group of groups.values()) group.posts.sort((a, b) => a.frontmatter.seriesOrder - b.frontmatter.seriesOrder);
  return [...groups.values()];
}
module.exports = { seriesPath, collectSeries };
