import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { Link } from "gatsby";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import { ArrowRight, Code2 } from "lucide-react";
import { collectProjectStories } from "../lib/projectStories.cjs";
import { postPath } from "../lib/content.cjs";
import { withSizes } from "../lib/images";
import "./projectStories.css";

const coverSizes = "(min-width: 761px) 360px, (min-width: 481px) 320px, calc(100vw - 88px)";
const transform = (x, y, z = 0, rx = 0, ry = 0, rz = 0) =>
  `translate3d(${x}px, ${y}px, 0) perspective(1200px) translateZ(${z}px) rotateX(${rx}deg) rotateY(${ry}deg) rotateZ(${rz}deg)`;
const stackPoint = (rank, x, step) => [x + rank * step, 38 - rank * 10, -rank * 55, 8, -14, -5 + rank * 6];
const between = (from, to, amount) => from.map((value, axis) => value + (to[axis] - value) * amount);
const frames = (pointAt) => Array.from({ length: 61 }, (_, step) => ({ transform: transform(...pointAt(step / 60)) }));
const ease = (t) => t * t * (3 - 2 * t);
const useBrowserLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

const CYCLE_MS = 1500;
// The front card is furthest out at this point, which is when it can pass
// behind the next card with the least overlap.
const TUCK_AT = 0.45;
// Cards behind the front one step forward a beat later, the back ones last.
const advance = (rank, t) => ease(Math.min(1, Math.max(0, (t - 0.04 - rank * 0.05) / 0.66)));
// Moves one axis from rest, through `via` at `speed`, back to rest. Keeping
// some axes moving while another turns around lets the card loop around the
// stack in one continuous arc instead of stopping at each pose.
function swing(start, via, end, speed, t) {
  const [from, to, fromSpeed, toSpeed, span] = t < TUCK_AT ? [start, via, 0, speed, TUCK_AT] : [via, end, speed, 0, 1 - TUCK_AT];
  const s = t < TUCK_AT ? t / TUCK_AT : (t - TUCK_AT) / span;
  return (2 * s ** 3 - 3 * s ** 2 + 1) * from + (s ** 3 - 2 * s ** 2 + s) * span * fromSpeed
    + (3 * s ** 2 - 2 * s ** 3) * to + (s ** 3 - s ** 2) * span * toSpeed;
}

function ProjectStory({ story }) {
  const root = useRef(null);
  const scene = useRef(null);
  const toggle = useRef(null);
  const restoreFocus = useRef(false);
  const motion = useRef([]);
  const [width, setWidth] = useState(1120);
  const [expanded, setExpanded] = useState(false);
  const [front, setFront] = useState(0);
  const [cycling, setCycling] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [visible, setVisible] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);
  const [reducedMotion, setReducedMotion] = useState(true);
  const count = story.posts.length;
  const mobile = width < 700;
  const canPlay = visible && pageVisible && !reducedMotion && !hovered && !focused && !expanded;
  const listId = `project-parts-${story.id}`;
  const copyHidden = expanded && !mobile;

  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const syncMotion = () => setReducedMotion(media.matches);
    const syncVisibility = () => setPageVisible(!document.hidden);
    syncMotion();
    syncVisibility();
    media.addEventListener("change", syncMotion);
    document.addEventListener("visibilitychange", syncVisibility);
    const resize = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width));
    resize.observe(scene.current);
    const intersection = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), { threshold: 0.2 });
    intersection.observe(root.current);
    return () => {
      resize.disconnect();
      intersection.disconnect();
      media.removeEventListener("change", syncMotion);
      document.removeEventListener("visibilitychange", syncVisibility);
    };
  }, []);

  useEffect(() => {
    if (!canPlay || cycling) return undefined;
    const timer = window.setTimeout(() => setCycling(true), 4200);
    return () => window.clearTimeout(timer);
  }, [canPlay, cycling, front]);

  useEffect(() => {
    if (reducedMotion) setCycling(false);
  }, [reducedMotion]);

  useEffect(() => {
    if (!restoreFocus.current) return;
    restoreFocus.current = false;
    if (expanded) root.current?.querySelector(".project-card-link")?.focus({ preventScroll: true });
    else toggle.current?.focus({ preventScroll: true });
  }, [expanded]);

  const changeExpanded = useCallback((shouldRestoreFocus = true) => {
    restoreFocus.current = shouldRestoreFocus;
    setCycling(false);
    setFront(0);
    setExpanded((value) => !value);
    if (scene.current) scene.current.scrollLeft = 0;
  }, []);

  useEffect(() => {
    if (!expanded) return undefined;
    const element = root.current;
    const closeOnEscape = (event) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      changeExpanded();
    };
    const closeOutsideCards = (event) => {
      // Ignore the opening click and preserve navigation from an article card.
      if (toggle.current?.contains(event.target)) return;
      const card = event.target.closest?.(".project-card");
      if (card && element.contains(card)) return;
      changeExpanded(false);
    };
    element.addEventListener("keydown", closeOnEscape);
    document.addEventListener("click", closeOutsideCards);
    return () => {
      element.removeEventListener("keydown", closeOnEscape);
      document.removeEventListener("click", closeOutsideCards);
    };
  }, [expanded, changeExpanded]);

  const cardWidth = mobile ? Math.min(320, width - 56) : Math.min(350, width * 0.34);
  const gap = mobile ? 18 : 28;
  const rowWidth = count * cardWidth + (count - 1) * gap;
  const expandedWidth = Math.max(width, rowWidth + (mobile ? 32 : 0));
  const rowStart = Math.max(mobile ? 16 : 0, (width - rowWidth) / 2);
  const baseX = mobile ? (width - cardWidth) / 2 - 10 : width * 0.24 - cardWidth / 2;
  const backStep = Math.min(28, 64 / Math.max(1, count - 1));
  const stackPose = (rank) => transform(...stackPoint(rank, baseX, backStep));

  // While a cycle runs, the cards' own styles already describe the stack after
  // it, so finishing (or cancelling) the animations never moves anything.
  useBrowserLayoutEffect(() => {
    if (!cycling) return undefined;
    const timing = { duration: CYCLE_MS, fill: "both" };
    const start = stackPoint(0, baseX, backStep);
    const end = stackPoint(count - 1, baseX, backStep);
    // Slide out and up, then drop behind the next card at the depth it has
    // reached, still moving down and back while turning around.
    const next = between(stackPoint(1, baseX, backStep), start, advance(1, TUCK_AT));
    const via = [start[0] + cardWidth * (mobile ? 0.1 : 0.34), start[1] - 10, next[2], start[3], start[4], start[5] + 12];
    const speed = [0, mobile ? 60 : 120, end[2] - start[2], 0, 0, end[5] - start[5]];
    const animations = [...root.current.querySelectorAll(".project-card")].flatMap((card, index) => {
      const rank = (index - front + count) % count;
      if (rank > 0) {
        const from = stackPoint(rank, baseX, backStep);
        const to = stackPoint(rank - 1, baseX, backStep);
        return [card.animate(frames((t) => between(from, to, advance(rank, t))), timing)];
      }
      return [
        card.animate(frames((t) => start.map((value, axis) => swing(value, via[axis], end[axis], speed[axis], t))), timing),
        card.animate([{ zIndex: count + 1 }, { zIndex: count + 1, offset: TUCK_AT }, { zIndex: 0, offset: TUCK_AT }, { zIndex: 0 }], timing),
      ];
    });
    motion.current = animations;
    Promise.all(animations.map((animation) => animation.finished)).then(() => {
      if (motion.current !== animations) return;
      setFront((value) => (value + 1) % count);
      setCycling(false);
    }, () => {});
    return () => {
      motion.current = [];
      animations.forEach((animation) => animation.cancel());
    };
  }, [cycling, front, count, baseX, backStep, cardWidth, mobile]);

  useEffect(() => {
    motion.current.forEach((animation) => {
      if (!canPlay) animation.pause();
      else if (animation.playState === "paused") animation.play();
    });
  }, [canPlay, cycling]);

  return (
    <article
      ref={root}
      className="project-story"
      data-expanded={expanded}
      data-mobile={mobile}
      data-motion={canPlay ? "playing" : "paused"}
      aria-labelledby={copyHidden ? `project-expanded-title-${story.id}` : `project-title-${story.id}`}
      onPointerEnter={(event) => { if (event.pointerType !== "touch") setHovered(true); }}
      onPointerLeave={() => setHovered(false)}
      onFocusCapture={() => setFocused(true)}
      onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false); }}
    >
      <div className="project-expanded-heading" hidden={!copyHidden}>
        <h3 id={`project-expanded-title-${story.id}`}>{story.title}</h3>
        <Link className="project-more" to={postPath(story.firstSlug)}>
          More <ArrowRight size={17} aria-hidden="true" />
          <span className="sr-only"> — start with part {story.posts[0].frontmatter.seriesOrder} of {story.title}</span>
        </Link>
      </div>
      <div className="project-scene" ref={scene}>
        <ol
          id={listId}
          className="project-deck"
          aria-label={`${story.title} articles in reading order`}
          aria-hidden={!expanded}
          style={{ width: expanded ? expandedWidth : "100%", "--project-card-width": `${cardWidth}px` }}
        >
          {story.posts.map((node, index) => {
            const post = node.frontmatter;
            const rank = (index - front + count) % count;
            const visualRank = cycling ? (rank + count - 1) % count : rank;
            const image = withSizes(getImage(post.featuredImage), coverSizes);
            return (
              <li
                key={node.id}
                className="project-card"
                data-rank={rank}
                style={{
                  transform: expanded ? transform(rowStart + index * (cardWidth + gap), mobile ? 14 : 66) : stackPose(visualRank),
                  zIndex: count - visualRank,
                }}
                onTransitionEnd={(event) => {
                  // A keyboard user can reach the next part before the row has
                  // finished opening. Keep that focused card in view afterward.
                  if (expanded && event.target === event.currentTarget && event.propertyName === "transform" && event.currentTarget.contains(document.activeElement)) {
                    event.currentTarget.scrollIntoView({ block: "nearest", inline: "nearest" });
                  }
                }}
              >
                <Link to={postPath(post.slug)} tabIndex={expanded ? 0 : -1} className="project-card-link">
                  <div className="project-card-cover">
                    {image ? <GatsbyImage image={image} alt="" /> : <div className="image-placeholder"><Code2 size={44} aria-hidden="true" /></div>}
                    <span className="card-series-badge">Part {post.seriesOrder}</span>
                  </div>
                  <div className="project-card-copy">
                    <h4>{post.title}</h4>
                    <span className="project-card-bottom">{node.fields.readingMinutes} min read <ArrowRight size={18} aria-hidden="true" /></span>
                  </div>
                </Link>
              </li>
            );
          })}
        </ol>
        <button
          ref={toggle}
          className="project-stack-hit"
          style={{ zIndex: count + 2 }}
          hidden={expanded}
          type="button"
          onClick={() => changeExpanded()}
          aria-expanded={expanded}
          aria-controls={listId}
          aria-label={`Show all ${count} parts of ${story.title}`}
        />
      </div>
      <div className="project-copy" aria-hidden={copyHidden}>
        <h3 id={`project-title-${story.id}`}>{story.title}</h3>
        <p>{story.description}</p>
        <Link className="project-more" to={postPath(story.firstSlug)} tabIndex={copyHidden ? -1 : 0}>
          More <ArrowRight size={18} aria-hidden="true" />
          <span className="sr-only"> — start with part {story.posts[0].frontmatter.seriesOrder} of {story.title}</span>
        </Link>
      </div>
      <p className="project-deck-caption">
        {count} parts · {expanded ? "Click outside the cards to stack them again" : "Click the stack to explore"}
        {expanded && <span className="sr-only">. Or press Escape.</span>}
      </p>
    </article>
  );
}

export default function ProjectStories({ nodes = [] }) {
  const [latest] = collectProjectStories(nodes);
  if (!latest) return null;
  return (
    <section id="projects" className="project-stories" aria-labelledby="projects-title">
      <div className="section-heading">
        <h2 id="projects-title">Latest project</h2>
        <Link className="subtle-link project-all-link" to="/projects/">All projects <ArrowRight size={17} aria-hidden="true" /></Link>
      </div>
      <ProjectStory key={latest.id} story={latest} />
    </section>
  );
}
