// Each project follows the same engineering workflow. Durations include putting
// tools down, so a greeting or coffee pause can interrupt it safely. The soldered
// board goes with him to the meter and back to the soldering spot afterwards.
export const WORKFLOW = [
  { name: "schematic", duration: 1.6 },
  { name: "solder", duration: 8.7 },
  { name: "code", duration: 8.5 },
  { name: "carry", duration: 2.8 },
  { name: "multimeter", duration: 6.5 },
  { name: "oscilloscope", duration: 6.5 },
  { name: "return", duration: 2.8 },
];

export function createActivity() {
  let index = 0;
  let elapsed = 0;
  return {
    get name() { return WORKFLOW[index].name; },
    get time() { return elapsed; },
    get duration() { return WORKFLOW[index].duration; },
    advance(dt) {
      elapsed += dt;
      let changed = false;
      while (elapsed >= WORKFLOW[index].duration) {
        elapsed -= WORKFLOW[index].duration;
        index = (index + 1) % WORKFLOW.length;
        changed = true;
      }
      return changed;
    },
    restartStep() { elapsed = 0; },
    next() {
      elapsed = 0;
      index = (index + 1) % WORKFLOW.length;
    },
  };
}

let greetingClaimed = false;
export function claimGreeting() {
  if (greetingClaimed) return false;
  greetingClaimed = true;
  return true;
}

// One introduction at startup, before the work loop begins.
export function createGreeting({ claim = () => true } = {}) {
  let pending = false;
  let elapsed = null;
  let used = false;
  const request = () => {
    if (used) return;
    used = true;
    if (claim()) pending = true;
  };
  return {
    get pending() { return pending; },
    get active() { return elapsed !== null; },
    get time() { return elapsed ?? 0; },
    request,
    // A nap the visitor asked for ends the introduction early.
    finish() { elapsed = null; },
    advance(dt, handsFree) {
      if (pending && handsFree) {
        pending = false;
        elapsed = 0;
      }
      if (elapsed === null) return;
      elapsed += dt;
      if (elapsed >= 4.6) elapsed = null;
    },
  };
}

export function greetingLine(time) {
  if (time >= 0.9 && time < 2.2) return "Hi there! I'm Ahmad.";
  if (time >= 2.2 && time < 3.8) return "Welcome to BrightBytes!";
  return "";
}
